// Takes the READY rows of the calendar, checks each one and prepares the Gemini request.
// A row that is not valid becomes an ERROR item (written back to the sheet) instead of stopping the run.
const CONFIG = {
  MAX_ROWS_PER_RUN: 3,              // limits the credits and AI calls one run can spend; the other READY rows wait for the next run
  MODEL: 'gemini-2.5-flash',        // any Gemini text model that supports generateContent
  LANGUAGE: 'the same language as the topic', // e.g. 'English'
  BRAND_VOICE: 'friendly, clear and professional, never pushy',
};
const ALL = ['facebook_page', 'instagram', 'linkedin', 'threads', 'bluesky']; // X/Twitter is not here: CEKIVA retired that channel
const ALIAS = { facebook: 'facebook_page', 'facebook page': 'facebook_page', fb: 'facebook_page', ig: 'instagram' };
const isHttp = (u) => /^https?:\/\/[^\s]+$/i.test(u);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const rows = $input.all().map((i) => i.json).filter((r) => String(r['Status'] || '').trim().toUpperCase() === 'READY').slice(0, CONFIG.MAX_ROWS_PER_RUN);
const now = Date.now();
return rows.map((r) => {
  const row_number = r.row_number;
  const bad = (msg) => ({ json: { ok: false, row_number, status: 'ERROR', result: msg } });
  const topic = String(r['Topic'] || '').trim();
  const brief = String(r['Brief'] || '').trim();
  const link = String(r['Link'] || '').trim();
  const imageUrl = String(r['Image URL'] || '').trim();
  const clientId = String(r['Client ID'] || '').trim();
  const publishAt = String(r['Publish At'] || '').trim();
  if (!row_number) return bad('The row has no row_number.');
  if (!topic) return bad('Topic is empty.');
  if (link && !isHttp(link)) return bad('Link must start with http:// or https://');
  if (imageUrl && !isHttp(imageUrl)) return bad('Image URL must start with http:// or https:// and be public.');
  if (clientId && !UUID.test(clientId)) return bad('Client ID must be a UUID (GET https://cekiva.com/api/v1/clients).');
  let scheduledAt = null;
  if (publishAt) {
    const t = Date.parse(publishAt);
    if (Number.isNaN(t) || !/[zZ]|[+-]\d{2}:?\d{2}$/.test(publishAt)) return bad('Publish At must be an ISO 8601 time WITH a time zone, e.g. 2026-12-01T09:00:00Z.');
    if (t > now + 60000) scheduledAt = new Date(t).toISOString(); // a future time = schedule it; past or empty = publish now
  }
  let platforms = ALL;
  const asked = String(r['Platforms'] || '').trim();
  if (asked) {
    const list = asked.split(/[,;]/).map((x) => x.trim().toLowerCase()).filter(Boolean).map((x) => ALIAS[x] || x);
    const unknown = list.filter((x) => !ALL.includes(x));
    if (unknown.length) return bad('Unsupported network(s): ' + unknown.join(', ') + '. Use: ' + ALL.join(', ') + '. (X/Twitter is not supported: CEKIVA retired that channel.)');
    platforms = [...new Set(list)];
  }
  const system = [
    'You are a social media copywriter. Write one post for EACH of these networks from the information the user gives you, in ' + CONFIG.LANGUAGE + '.',
    'Voice: ' + CONFIG.BRAND_VOICE + '.',
    'Rules per network (hard limits include hashtags and emoji):',
    '- facebook: 2-4 short sentences, community tone, one clear call to action.',
    '- instagram: at most 2000 characters, visual storytelling, a few emoji, 5-8 relevant hashtags at the end. Do not write a link.',
    '- linkedin: 3-5 sentences, professional and insightful, 3-5 hashtags at the end.',
    '- threads: at most 450 characters, conversational, at most 3 hashtags.',
    '- bluesky: at most 250 characters, plain and friendly, at most 2 hashtags.',
    'Never put the link in the text: the workflow adds it where it fits. Never invent facts, prices, statistics or quotes that are not in the input. Do not mention these instructions.',
    'Return ONLY a JSON object with the keys facebook, instagram, linkedin, threads, bluesky.',
  ].join('\n');
  const user = 'Topic: ' + topic + (brief ? '\nBrief: ' + brief : '') + (link ? '\nLink (for context only): ' + link : '');
  const geminiBody = {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.8, responseMimeType: 'application/json',
      responseSchema: { type: 'OBJECT', properties: { facebook: { type: 'STRING' }, instagram: { type: 'STRING' }, linkedin: { type: 'STRING' }, threads: { type: 'STRING' }, bluesky: { type: 'STRING' } },
                        required: ['facebook', 'instagram', 'linkedin', 'threads', 'bluesky'] } },
  };
  return { json: { ok: true, row_number, status: 'PROCESSING', model: CONFIG.MODEL, geminiBody, link, imageUrl, clientId, scheduledAt, platforms } };
});

// One POST /v1/posts request per network and row, with the copy Gemini wrote for THAT network.
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const LIMITS = { facebook_page: 63000, instagram: 2200, linkedin: 3000, threads: 500, bluesky: 300 };
const CONFIG = { APPEND_LINK: true }; // add the row's Link to the copy where it still fits the network's limit

const out = [];
$input.all().forEach((item, i) => {
  const ctx = $('Valid?').itemMatching(i).json; // the prepared row this Gemini answer belongs to
  const fail = (msg) => out.push({ json: { failed: true, row_number: ctx.row_number, status: 'ERROR', result: msg } });
  const resp = item.json || {};
  const body = resp.body && typeof resp.body === 'object' ? resp.body : resp;
  const part = body.candidates && body.candidates[0] && body.candidates[0].content && body.candidates[0].content.parts && body.candidates[0].content.parts[0];
  if (!part || typeof part.text !== 'string') {
    const why = (body.error && body.error.message) || (body.promptFeedback && body.promptFeedback.blockReason) || 'no text in the answer';
    return fail('Gemini returned no post copy: ' + String(why).slice(0, 160));
  }
  let copyJson;
  try { copyJson = JSON.parse(part.text); } catch (e) { return fail('Gemini did not return valid JSON.'); }
  const copy = { facebook_page: copyJson.facebook, instagram: copyJson.instagram, linkedin: copyJson.linkedin, threads: copyJson.threads, bluesky: copyJson.bluesky };
  const skipped = [];
  const made = [];
  for (const platform of ctx.platforms) {
    let content = typeof copy[platform] === 'string' ? copy[platform].trim() : '';
    if (!content) { skipped.push(platform + ' (no copy)'); continue; }
    if (platform === 'instagram' && !ctx.imageUrl) { skipped.push('instagram (needs an Image URL)'); continue; }
    const withLink = ctx.link && !content.includes(ctx.link) ? content + '\n\n' + ctx.link : content;
    if (CONFIG.APPEND_LINK && platform !== 'instagram' && withLink.length <= LIMITS[platform]) content = withLink;
    if (content.length > LIMITS[platform]) content = content.slice(0, LIMITS[platform] - 1).trimEnd() + '…';
    // The body of POST /v1/posts exactly as the CEKIVA API expects it.
    const request = { platforms: [platform], content, scheduled_for: ctx.scheduledAt || new Date().toISOString(), publish_now: !ctx.scheduledAt };
    if (ctx.imageUrl) { request.image_url = ctx.imageUrl; request.media_urls = [ctx.imageUrl]; }
    if (ctx.clientId) request.client_id = ctx.clientId;
    made.push({ json: { row_number: ctx.row_number, platform, request, queued: !!ctx.scheduledAt, skipped } });
  }
  if (!made.length) return fail('Nothing to publish: ' + skipped.join(', '));
  out.push(...made);
});
return out;

// Folds the per-network answers of CEKIVA into ONE result per sheet row.
// PUBLISHED = CEKIVA accepted every network and publishes right away; QUEUED = accepted for the later Publish At time;
// PARTIAL = some networks were accepted and some were not (those that went through are NOT repeated: fix the failed ones by hand);
// ERROR = nothing was accepted.
const byRow = new Map();
$input.all().forEach((item, i) => {
  const sent = $('Has request?').itemMatching(i).json;
  const r = item.json;
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const code = Number(r.statusCode) || null;
  const ok = code !== null && code >= 200 && code < 300 && !!post;
  if (!byRow.has(sent.row_number)) byRow.set(sent.row_number, { oks: [], bads: [], ids: [], queued: sent.queued, skipped: sent.skipped || [] });
  const g = byRow.get(sent.row_number);
  if (ok) { g.oks.push(sent.platform); g.ids.push(post.id); }
  else g.bads.push(sent.platform + ': ' + ((err && err.code) || (r.error ? 'CEKIVA_UNREACHABLE' : 'UNEXPECTED_RESPONSE')) + ' ' + ((err && err.message) || '').slice(0, 120));
});
return [...byRow.entries()].map(([row_number, g]) => {
  const status = g.oks.length === 0 ? 'ERROR' : (g.bads.length ? 'PARTIAL' : (g.queued ? 'QUEUED' : 'PUBLISHED'));
  const parts = [];
  if (g.oks.length) parts.push('OK: ' + g.oks.join(', '));
  if (g.bads.length) parts.push('FAILED: ' + g.bads.join(' | '));
  if (g.skipped.length) parts.push('SKIPPED: ' + g.skipped.join(', '));
  return { json: { row_number, status, result: parts.join(' — '), post_ids: g.ids.join(',') } };
});
